import assert from 'node:assert/strict';import {readFileSync,writeFileSync,existsSync,openSync,closeSync,mkdirSync} from 'node:fs';import {resolve} from 'node:path';import {createHash,randomUUID} from 'node:crypto';import {DatabaseSync,backup} from 'node:sqlite';import {Tracer} from '../../src/index.ts';import {SQLiteRepository} from '../../src/persistence/sqlite.ts';import {observeLocal} from '../../src/interfaces/local-observer.ts';import {startHeadlessServer} from '../../src/interfaces/headless-server.ts';import {createClient} from '../../src/client.ts';import {verificationFixture} from '../../test/verification-fixture.ts';import {installAssessmentFixture} from '../../test/pair-verification-fixture.ts';
const procedure='output/configuration-change/execute-research-follow-through.mjs',methodPath='projects/tracer/configuration-research-method.json',destination='projects/tracer/configuration-research-follow-through.json',journal='output/configuration-change/research-follow-through-journal.json';assert.ok(!existsSync(destination)&&!existsSync(journal));const declaration=JSON.parse(readFileSync(methodPath)),hash=x=>createHash('sha256').update(x).digest('hex');assert.equal(hash(readFileSync(procedure)),declaration.procedure.sha256);const actor={actor:'tracer-research-cohort-analysis',reason:'Execute actual arithmetic over retained synthetic cohort CSV states and compose unchanged research criteria with exact before/after candidate verification. No physical experiment or representative-human validation claim.'};
const f=await verificationFixture('research'),state={actor,commands:[]};const save=extra=>writeFileSync(journal,JSON.stringify({...state,...extra},null,2)+'\n');let server,completed=false;save({status:"initialised_disposable_research_project",database:f.database});
try{let observations=0;const t=new Tracer(f.repository,undefined,async locator=>{observations++;return observeLocal(locator)});const {pin}=await installAssessmentFixture({...f,tracer:t},'research');let schema=await t.getSchema();await t.setSchema({entityTypes:schema.entityTypes,relationshipTypes:{...schema.relationshipTypes,contextual_reference:{resourceTarget:true,reference:true,fields:{}}}},schema.version,actor);schema=await t.getSchema();
const acceptance='AC-1: The current cohort arithmetic mean shall be at most 15. AC-2: Its mean increase over the fixed baseline shall be at most 2.',split=acceptance.indexOf(' AC-2:'),field=f.definition.requirement.fields.acceptance[0];const requirement=await t.updateEntity(f.requirement.id,1,{fields:{...f.requirement.fields,[f.definition.requirement.fields.title]:'Synthetic cohort stability hypothesis',[f.definition.requirement.fields.statement]:'Evaluate the declared cohort mean and change from its fixed baseline using all retained sample values.',[field]:acceptance}},schema.version,actor);const method=await t.updateEntity(f.method.id,1,{fields:{...f.method.fields,[f.definition.method.fields.title]:'Arithmetic cohort comparison',[f.definition.method.fields.procedure]:'Read all five numeric CSV sample values. Compute arithmetic current and fixed-baseline means; compare current mean with 15 and its increase with 2. Retain the independently identified baseline replication use.',[f.definition.method.fields.expected]:'Both unchanged numeric criteria must pass; retained baseline bytes must match both B references.'}},schema.version,actor);
const directory='projects/tracer/research-cohort';mkdirSync(directory,{recursive:true});const beforePath=directory+'/before.csv',currentPath=directory+'/current.csv',afterPath=directory+'/after.csv';for(const path of [beforePath,currentPath,afterPath])assert.ok(!existsSync(path));const csv=values=>'value\n'+values.join('\n')+'\n';writeFileSync(beforePath,csv(declaration.baseline));writeFileSync(currentPath,readFileSync(beforePath));
const resource=await t.createEntity({type:'@resource',fields:{},resource:{label:'Retained synthetic cohort data',source:{system:'file',externalId:currentPath}}},schema.version,actor),B=await t.evidence.observe({entityId:resource.id,locator:{system:'file',path:resolve(currentPath)}},actor);const refs=[];for(const role of ['fixed baseline','current cohort','baseline replication'])refs.push(await t.createRelationship({type:'contextual_reference',source:requirement.id,target:resource.id,fields:{},reference:{role,explanation:'A distinct evaluated use of the same reusable cohort resource; select exact observed bytes.',state:{mode:'pinned',observationId:B.id}}},schema.version,actor));
const capture=async(name,observation)=>{const context=await t.configurations.captureContext();const input={id:randomUUID(),name,subjectId:requirement.id,expectedSubjectVersion:requirement.version,members:[requirement,method,f.profile,resource].map(e=>({entityId:e.id,version:e.version})),relationships:[f.relationship,...refs].map(e=>({relationshipId:e.id,version:e.version})),content:[{entityId:resource.id,observationId:observation.id}],scope:{purpose:'Declared synthetic cohort hypothesis, arithmetic protocol and independently selected data uses',coverage:'partial',rationale:'All defined numeric criteria are tested; no undeclared experiment, physical population or lab-wide impact is inferred.'},expectedSchemaVersion:context.schema.version,expectedProjectRevision:context.projectRevision,expectedEvidenceRevision:context.evidenceRevision};save({pendingCapture:input});return t.configurations.captureExact(input,actor);};const before=await capture('Research cohort before: B/B/B uses',B);state.before=before;
server=await startHeadlessServer(t,{port:0,provenance:actor});const c=createClient({baseUrl:server.origin});await c.connect();const write=async(path,input)=>{save({pending:{path,input}});const result=await c.write(path,input);state.commands.push({path,input,result});save({});return result;};
const basis={model:{entityId:f.profile.id,version:1,field:'definition'},requirement:{entityId:requirement.id,version:requirement.version},coverage:{kind:'complete',rationale:'Two exact unchanged numeric acceptance clauses, with one explicit arithmetic protocol.'},criteria:[{id:'AC-1',field,start:0,end:split,quote:acceptance.slice(0,split)},{id:'AC-2',field,start:split+1,end:acceptance.length,quote:acceptance.slice(split+1)}],methods:[{entityId:method.id,version:method.version,relationship:{id:f.relationship.id,version:1},criterionIds:['AC-1','AC-2']}]};let model=await t.verification.resolveModel(basis.model);const opening={commandId:randomUUID(),caseId:randomUUID(),membershipId:randomUUID(),title:'Research cohort arithmetic evidence',purpose:'Measure the exact selected synthetic dataset, preserve old candidate conclusions and independently pinned baseline uses.',basis,targetConfigurationId:before.id,targetPolicy:'target-reference-uses-v2',additionalFields:{},expectedSchemaVersion:model.context.schemaVersion,expectedProjectRevision:model.context.projectRevision,expectedEvidenceRevision:model.context.evidenceRevision};await write('/api/verifications/open',opening);const selection={caseId:opening.caseId,openingCommandId:opening.commandId};state.selection=selection;const analyze=()=>c.read('/api/verification-analysis',selection),guards=a=>({...selection,expectedSchemaVersion:a.view.model.context.schemaVersion,expectedProjectRevision:a.view.model.context.projectRevision,expectedEvidenceRevision:a.view.model.context.evidenceRevision,expectedCaseVersion:a.view.case.version}),mutation=(a,reason)=>({...guards(a),commandId:randomUUID(),expectedAnalysisDigest:a.proposalDigest,reason});
const mean=path=>{const text=readFileSync(path,'utf8'),values=text.trim().split('\n').slice(1).map(Number);assert.equal(values.length,5);assert.ok(values.every(Number.isFinite));return {mean:values.reduce((sum,x)=>sum+x,0)/values.length,values,sha256:hash(text)};};const runs=[];
async function perform(currentFile,observation){assert.equal('sha256:'+hash(readFileSync(beforePath)),B.hash);assert.equal('sha256:'+hash(readFileSync(currentFile)),observation.hash);const baseline=mean(beforePath),current=mean(currentFile),replication=mean(beforePath),increase=current.mean-baseline.mean;assert.equal(replication.mean,baseline.mean);const results=[{criterionId:'AC-1',outcome:current.mean<=15?'passed':'failed',actual:`Current arithmetic mean ${current.mean}; five values ${JSON.stringify(current.values)}; limit 15.`,rationale:'Computed from every numeric sample in the exact selected current-cohort byte state.'},{criterionId:'AC-2',outcome:increase<=2?'passed':'failed',actual:`Fixed baseline mean ${baseline.mean}; current mean ${current.mean}; increase ${increase}; limit 2. Replication mean ${replication.mean}.`,rationale:'Both independently identified baseline uses match retained B bytes; current use is measured from its independently selected state.'}];let a=await analyze();const executionId=randomUUID();const executed=await write('/api/verifications/execute',{...guards(a),commandId:randomUUID(),executionId,membershipId:randomUUID(),title:'Measured synthetic cohort '+(runs.length+1),methodId:method.id,source:{kind:'performed'},conditions:{baseline:{path:beforePath,...baseline},current:{path:currentFile,...current},replicationMean:replication.mean,procedure:{path:procedure,sha256:declaration.procedure.sha256},qualification:'Actual arithmetic on synthetic CSVs, not a physical experiment or representative-human validation.'},results,inputs:[B,observation,B].map((obs,i)=>({entityId:resource.id,facet:'content',observationId:obs.id,referenceId:refs[i].id,role:refs[i].reference.role})),relationshipInputs:refs.map(ref=>({id:ref.id,revision:ref.version})),additionalFields:{}});a=await analyze();await write('/api/verifications/select',{...mutation(a,'Select the actual arithmetic results; explicitly retain all earlier candidate measurements.'),selections:['AC-1','AC-2'].map(criterionId=>({criterionId,methodId:method.id,executionId})),accounting:a.executions.map(x=>x.id===executionId?{executionId:x.id,decision:'selected',rationale:'Actual measured means for this exact target and all unchanged criteria.'}:{executionId:x.id,decision:'superseded',replacementId:executionId,rationale:'The new candidate uses different selected current-cohort bytes; retain the old measured outcomes and target context.'})});a=await analyze();assert.equal(a.ready,true);const conclusion=await write('/api/verifications/conclude',mutation(a,'Both unchanged numeric criteria have measured applicable passing results, exact reference-use correspondence and complete activity accounting.'));const run={executionId,executed,conclusion,baseline,current,increase,results};runs.push(run);return run;}
const first=await perform(beforePath,B);const priorConclusion=await analyze();assert.equal(priorConclusion.completion.state,'verified');writeFileSync(currentPath,csv(declaration.after));writeFileSync(afterPath,readFileSync(currentPath));const C=await t.evidence.observe({entityId:resource.id,locator:{system:'file',path:resolve(currentPath)}},actor);assert.notEqual(B.hash,C.hash);refs[1]=await t.updateRelationship(refs[1].id,1,{type:refs[1].type,source:refs[1].source,target:refs[1].target,fields:{},reference:{...refs[1].reference,state:{mode:'pinned',observationId:C.id}}},schema.version,actor);const after=await capture('Research cohort after: B/C/B uses',C);state.after=after;assert.equal((await analyze()).completion.state,'verified','Unrelated live state must not invalidate the fixed before target');assert.deepEqual((await analyze()).recordedConclusion,priorConclusion.recordedConclusion);const comparison=await t.configurations.compare({beforeId:before.id,afterId:after.id});assert.equal(comparison.content[0].content,'different');assert.equal(comparison.members.find(x=>x.id===resource.id).state,'unchanged');assert.equal(comparison.relationships.filter(x=>x.state==='modified').length,1);
let context=await t.applicationModels.resolve(pin);const assessmentOpening={commandId:randomUUID(),assessmentId:randomUUID(),title:'Assess research cohort B to C',purpose:'Recompute the unchanged numeric criteria for independently selected B/C/B material uses; old B-only results do not establish C.',model:pin,query:{source:'configuration_pair',beforeId:before.id,afterId:after.id,policy:'scoped-reference-dependencies-v1',rootId:resource.id,direction:'outgoing',relationshipTypes:[],depth:1},additionalFields:{},expectedSchemaVersion:context.context.schemaVersion,expectedProjectRevision:context.context.projectRevision,expectedEvidenceRevision:context.context.evidenceRevision};await write('/api/change-assessments/open',assessmentOpening);const assessment={assessmentId:assessmentOpening.assessmentId,openingCommandId:assessmentOpening.commandId};state.assessment=assessment;const assess=()=>c.read('/api/assessment-analysis',assessment),assessmentBase=v=>({...assessment,expectedSchemaVersion:v.model.context.schemaVersion,expectedProjectRevision:v.model.context.projectRevision,expectedEvidenceRevision:v.model.context.evidenceRevision,expectedAssessmentVersion:v.assessment.version});let aa=await assess();const root={kind:'entity',id:resource.id},rootBasis=aa.obligations.find(x=>x.subject.id===resource.id),rootRequest={...assessmentBase(aa.view),commandId:randomUUID(),subject:root,dispositionId:randomUUID(),membershipId:randomUUID(),expectedDispositionVersion:0,expectedBasisDigest:rootBasis.currentDigest,title:'Recompute the changed current-cohort use',decision:'reverify',rationale:'Data bytes and the current-cohort reference revision changed; baseline and replication remain pinned to B. Recompute both unchanged numerical criteria against after C without rewriting the old B result.',actions:[{id:randomUUID(),kind:'reverify',title:'Measure exact B/C/B uses',state:'open',resolution:'',support:[]}],support:[],additionalFields:{}};await write('/api/change-assessments/disposition',rootRequest);
let a=await analyze();await write('/api/verifications/reopen',mutation(a,'The before conclusion remains valid for before B; explicitly start verification of the newly selected after candidate.'));a=await analyze();await write('/api/verifications/revise',{...mutation(a,'Keep all exact criterion/method identities and map both criteria while selecting after B/C/B.'),basis,targetConfigurationId:after.id,targetPolicy:'target-reference-uses-v2',mapping:['AC-1','AC-2'].map(id=>({fromId:id,toId:id}))});const second=await perform(afterPath,C);assert.equal(first.current.mean,12);assert.equal(first.increase,0);assert.equal(second.current.mean,13);assert.equal(second.increase,1);
aa=await assess();await write('/api/change-assessments/refresh',{...assessmentBase(aa.view),commandId:randomUUID(),reason:'Discover after-candidate execution/selection/conclusion evidence while retaining all before obligations.'});aa=await assess();const rootPrior=await t.changeAssessments.disposition(assessment,root);const wrong={...assessmentBase(aa.view),commandId:randomUUID(),subject:root,dispositionId:rootPrior.id,membershipId:rootPrior.membershipId,expectedDispositionVersion:rootPrior.version,expectedBasisDigest:aa.obligations.find(x=>x.subject.id===resource.id).currentDigest,title:rootPrior.title,decision:'reverify',rationale:rootPrior.rationale,actions:rootPrior.actions.map(action=>({...action,state:'done',resolution:'Attempt to reuse original B-only proof; must reject for C.',support:[{kind:'receipt',id:first.conclusion.receipt.id,mode:'configuration',configurationId:after.id}]})),support:[],additionalFields:{}};const frozen=await t.exportProject();save({pendingExpectedRefusal:wrong});await assert.rejects(c.write('/api/change-assessments/disposition',wrong));assert.equal(await t.evaluations.getOutcome(wrong.commandId),null);assert.deepEqual(await t.exportProject(),frozen);state.beforeProofRejectedForAfterWithoutWrites=true;
const subjects=aa.obligations.map(x=>x.subject);for(const subject of subjects){aa=await assess();const obligation=aa.obligations.find(x=>x.subject.kind===subject.kind&&x.subject.id===subject.id),prior=await t.changeAssessments.disposition(assessment,subject);assert.equal(obligation.hasUnknown,false);const isRoot=subject.kind==='entity';const actions=isRoot?prior.actions.map(action=>({...action,state:'done',resolution:'Actual current mean 13 and increase 1 pass unchanged limits 15 and 2, using B/C/B states.',support:[{kind:'receipt',id:second.conclusion.receipt.id,mode:'configuration',configurationId:after.id}]})):[];await write('/api/change-assessments/disposition',{...assessmentBase(aa.view),commandId:randomUUID(),subject,dispositionId:prior?.id??randomUUID(),membershipId:prior?.membershipId??randomUUID(),expectedDispositionVersion:prior?.version??0,expectedBasisDigest:obligation.currentDigest,title:isRoot?'Actual B/C/B recomputation complete':'Account for retained cohort evidence '+subject.id.slice(0,8),decision:isRoot?'reverify':'no_action',rationale:isRoot?'Genuine exact-after controlled conclusion covers all three independent material uses and both unchanged criteria. Original B mean 12/delta 0 remains historical.':'This known declared material-use scope is accounted for by the actual after recomputation and controlled conclusion; retain original execution/control outcomes and do not claim old B-only results prove C. No separate data-quality or physical experiment claim is introduced.',actions,support:[],additionalFields:{}});}
aa=await assess();assert.ok(aa.obligations.every(x=>x.state==='accounted'&&x.openActions===0));await write('/api/change-assessments/close',{...assessmentBase(aa.view),commandId:randomUUID(),reason:'Every declared cohort candidate is accounted, actual exact-after arithmetic passes both unchanged criteria, and original results remain retained. Complete only this synthetic analytical scope.'});const final=await assess(),verification=await analyze();assert.equal(final.completion.state,'completed');assert.equal(verification.completion.state,'verified');assert.equal(verification.view.case.version,9);assert.equal(verification.executions.length,2);assert.deepEqual(await t.evaluations.getOutcome(first.conclusion.receipt.commandId??state.commands.find(x=>x.result.receipt.id===first.conclusion.receipt.id).input.commandId),first.conclusion);assert.deepEqual(await t.configurations.get(before.id),before);assert.deepEqual(await t.configurations.get(after.id),after);assert.equal(observations,2,'Capture/analysis must not perform implicit observer IO');const exported=await t.exportProject();for(const command of state.commands)assert.deepEqual(await c.read('/api/evaluation-outcome',{commandId:command.input.commandId}),command.result);assert.deepEqual(await t.exportProject(),exported);
const backupPath='projects/tracer/backups/research-configuration-change-complete.sqlite';closeSync(openSync(backupPath,'wx'));const sourceDb=new DatabaseSync(f.database,{readOnly:true});try{await backup(sourceDb,backupPath)}finally{sourceDb.close()}const restored=new SQLiteRepository(backupPath);try{const copy=new Tracer(restored);assert.deepEqual(await copy.exportProject(),exported);assert.deepEqual(await copy.verification.analyze(selection),verification);assert.deepEqual(await copy.changeAssessments.analyze(assessment),final)}finally{restored.close()}
const report={date:'2026-10-28',status:'actual_synthetic_research_analysis_and_pair_follow_through_completed',domain:'Research cohort stability with numeric analytical results and independently pinned baseline/current/replication uses',method:{path:methodPath,sha256:hash(readFileSync(methodPath))},procedure:{path:procedure,sha256:hash(readFileSync(procedure)),source:readFileSync(procedure,'utf8')},criteria:acceptance,before:before.id,after:after.id,pairDigest:comparison.basis.digest,comparison:{content:comparison.content,relationships:comparison.relationships,members:comparison.members,completeness:comparison.completeness},observations:{B,C,explicitObserverCalls:observations},dataFiles:[beforePath,currentPath,afterPath].map(path=>({path,sha256:hash(readFileSync(path)),csv:readFileSync(path,'utf8')})),runs:runs.map(run=>({executionId:run.executionId,conclusionReceiptId:run.conclusion.receipt.id,baseline:run.baseline,current:run.current,increase:run.increase,results:run.results})),verification:{selection,caseVersion:9,activities:2,state:verification.completion.state},assessment:{selection:assessment,state:final.completion.state,candidates:final.obligations.length,openActions:0,discovery:final.discovery},negative:{originalBeforeProofRejectedForAfterWithoutWrites:true},preservation:{beforeCaptureAndOriginalConclusionRetained:true,onlyExplicitObservations:true,onlineBackup:backupPath,restoredExportAndAnalysesExact:true,canonicalExportSha256:hash(JSON.stringify(exported))},commands:state.commands.map(command=>({path:command.path,commandId:command.input.commandId,receiptId:command.result.receipt.id})),qualifications:['Actual arithmetic was performed on all retained synthetic data values; no physical experiment, statistical population inference, human validation or regulatory claim.','Partial engineering scope and unassessed passage relevance remain explicit.','This proves the configured second-domain task; full original REQ-035 acceptance still requires its complete audit.']};writeFileSync(destination,JSON.stringify(report,null,2)+'\n');save({status:'completed',report:destination,nativeRevision:exported.projectRevision,caseVersion:9,candidates:final.obligations.length,openActions:0});completed=true;console.log(JSON.stringify({report:destination,means:[first.current.mean,second.current.mean],increase:second.increase,caseVersion:9,assessment:final.completion.state,candidates:final.obligations.length,backup:backupPath}));
}finally{await server?.close();if(!completed){const rescue='output/configuration-change/research-incomplete-'+randomUUID()+'.sqlite';closeSync(openSync(rescue,'wx'));const db=new DatabaseSync(f.database,{readOnly:true});try{await backup(db,rescue)}finally{db.close()}state.rescueBackup=rescue;save({status:'failed_or_interrupted_attempt_preserved'});}f.close()}
